"home.about.bhoomishaktiIsACollectionOf": "പരസ്പരം പൂരകമായ കാർഷിക കണ്ടുപിടിത്തങ്ങളുടെ ഒരു കൂട്ടമാണ് BhoomiShakti. ഓരോ പ്രോജക്ടും കൃഷിയുടെ ഓരോ തലത്തെയാണ് കൈകാര്യം ചെയ്യുന്നത് — ഇന്റലിജൻസ്, ഡിജിറ്റൽ ബന്ധങ്ങൾ മുതൽ യന്ത്രങ്ങൾ, വിത്ത്, മണ്ണ്, ഗ്രാമീണ പുനരുപയോഗ വിഭവങ്ങൾ വരെ.",
