"seva.overview.farmLabourAndLoadingunloadingWorkers": "കൃഷിപ്പണിക്കാരെയും കയറ്റിറക്ക് തൊഴിലാളികളെയും ഏർപ്പാടാക്കാൻ പ്രയാസം",
"seva.overview.transportVehiclesDependOnPersonal": "വാഹനങ്ങൾ കിട്ടുന്നത് വ്യക്തിപരമായ പരിചയങ്ങളെ ആശ്രയിച്ചാണ്",
"seva.overview.discoveryReliesOnPhoneCalls": "ഫോൺ വിളികൾ, ഇടനിലക്കാർ, പരിചയക്കാർ എന്നിവരെ ആശ്രയിച്ചാണ് കണ്ടെത്തൽ",
"seva.overview.unclearEquipmentAvailabilityProviderInformation": "യന്ത്ര ലഭ്യത, സേവനദാതാവിന്റെ വിവരം, നിരക്ക് എന്നിവയിൽ വ്യക്തതയില്ല",
"seva.overview.oneDigitalServicePlatform": "ഒരൊറ്റ ഡിജിറ്റൽ സേവന പ്ലാറ്റ്‌ഫോം",
"seva.overview.farmersDiscoverAndRequestAgricultural": "യന്ത്രങ്ങൾ, തൊഴിലാളികൾ മുതൽ വാഹനവും മറ്റ് കൃഷി സേവനങ്ങളും വരെ കർഷകർ ഒരൊറ്റ പ്ലാറ്റ്‌ഫോമിൽ കണ്ടെത്തി ആവശ്യപ്പെടുന്നു — പരിശോധിച്ച സേവനദാതാക്കൾ, ലളിതമായ പണമടയ്ക്കൽ, റേറ്റിംഗുകൾ എന്നിവയോടെ.",
