"s4.overview.sowingThatIsEvenEasier": "ഒരേപോലെയുള്ള, <t0>എളുപ്പമുള്ള, ചൂട് കുറഞ്ഞ</t0> വിത.",
"s4.overview.solarEnergyBatteryPowerControlled": "സോളാർ ഊർജം, ബാറ്ററി, നിയന്ത്രിത കമ്പനം, വിത്ത് ഒഴുക്ക് നിയന്ത്രണം, മുതുകിൽ തൂക്കാവുന്ന രൂപം, തണൽ — എല്ലാം ചെലവ് കുറഞ്ഞ ഒരൊറ്റ ഉപകരണത്തിൽ.",
"s4.overview.manualSeedSowingIsHard": "കൈകൊണ്ടുള്ള വിത കഠിനമായ പണിയാണ്",
"s4.overview.unevenSeedDistribution": "വിത്ത് ഒരേപോലെ വീഴുന്നില്ല",
"s4.overview.highManualLabourRequirement": "കൂടുതൽ കൈപ്പണി വേണം",
"s4.overview.heatStressDuringFieldWork": "വയലിലെ പണിക്കിടെ ചൂട് കൊണ്ടുള്ള ക്ഷീണം",
"s4.overview.timeconsumingSowing": "വിതയ്ക്ക് കൂടുതൽ സമയം",
"s4.overview.lackOfAffordableAgriculturalMachinery": "ചെലവ് കുറഞ്ഞ കാർഷിക യന്ത്രങ്ങളുടെ കുറവ്",
"s4.overview.aPortableSolarassistedSeedSower": "കൊണ്ടുനടക്കാവുന്ന, സോളാർ സഹായത്തോടെയുള്ള വിത്ത് വിതയ്ക്കൽ യന്ത്രം",
"s4.overview.aLowcostPortableSolarassistedBackpackbased": "കർഷകന്റെ സൗകര്യം കൂട്ടുന്നതോടൊപ്പം നിയന്ത്രിതവും താരതമ്യേന ഒരേപോലെയുമുള്ള വിത്ത് വിതരണം നൽകുന്ന, ചെലവ് കുറഞ്ഞ, കൊണ്ടുനടക്കാവുന്ന, സോളാർ സഹായത്തോടെയുള്ള, മുതുകിൽ തൂക്കാവുന്ന സംവിധാനം.",
"s4.overview.solar": "<t0/>സോളാർ",
"s4.overview.battery": "<t0/>ബാറ്ററി",
"s4.overview.vibration": "<t0/>കമ്പനം",
