"s4.how.vibrationKeepsSeedsFlowingThe": "കമ്പനം വിത്തുകളെ ഒഴുകിക്കൊണ്ടിരിക്കാൻ സഹായിക്കുന്നു; വേഗ നിയന്ത്രണം വിളയ്ക്കനുസരിച്ച് വിതയുടെ തോത് ക്രമീകരിക്കുന്നു.",
