"s4.story.scrolldrivenSeedFlow": "സ്ക്രോൾ ചെയ്യുമ്പോൾ വിത്ത് ഒഴുക്ക്",
"s4.story.watchS4ComeAlive": "S4 <t0>പ്രവർത്തിക്കുന്നത് കാണുക.</t0>",
"s4.story.scrollDownEachPartActivates": "താഴേക്ക് സ്ക്രോൾ ചെയ്യുക: ഓരോ ഭാഗവും ക്രമമായി പ്രവർത്തിക്കുന്നു, വിത്തുകൾ സംഭരണിയിൽ നിന്ന് രണ്ട് പൈപ്പുകളിലൂടെ മണ്ണിലേക്ക് എത്തുന്നു. ആശയ ചിത്രീകരണം.",
"s4.story.conceptualDiagramOfBhoomishaktiS4": "BhoomiShakti S4-ന്റെ ആശയ ചിത്രം: സോളാർ കുട, ബാറ്ററി, വേഗ നിയന്ത്രണം, കമ്പന മോട്ടോർ, വിത്ത് സംഭരണി, രണ്ട് പൈപ്പുകൾ, മണ്ണ്",
