"s4.story.theRechargeableBatteryStoresEnergy": "റീചാർജ് ചെയ്യാവുന്ന ബാറ്ററി ഊർജം സംഭരിക്കുന്നു — വൈദ്യുതി കുറവുള്ളിടത്ത് ഉപകാരപ്രദം.",
