"s4.story.motorVibration": "മോട്ടോറും കമ്പനവും",
"s4.story.vibrationMotorsStartTheAnticlogging": "കമ്പന മോട്ടോറുകൾ തുടങ്ങുന്നു — അടഞ്ഞുപോകാതിരിക്കാനുള്ള സംവിധാനം വിത്തുകളെ നീങ്ങിക്കൊണ്ടിരിക്കാൻ സഹായിക്കുന്നു.",
"s4.story.seedsLeaveStorage": "വിത്തുകൾ സംഭരണിയിൽ നിന്ന് പുറത്തേക്ക്",
