"jeevadhara.overview.feedTheSoilNotJust": "മണ്ണിനെ പോഷിപ്പിക്കുക, <t0>വിളയെ മാത്രമല്ല.</t0>",
"jeevadhara.overview.aSustainableModelCombiningOrganic": "ജൈവ പോഷക പരിപാലനം, നിയന്ത്രിത ജൈവ നൈട്രജൻ, മണ്ണിലെ ജൈവ പ്രവർത്തനം, യന്ത്രം കൊണ്ട് മണ്ണിൽ ചേർക്കൽ എന്നിവ ഒന്നിപ്പിക്കുന്ന സുസ്ഥിര മാതൃക.",
