"jeevadhara.overview.highLabourRequirementForOrganic": "ജൈവ കൃഷിക്ക് കൂടുതൽ തൊഴിലാളികൾ വേണം",
"jeevadhara.overview.unevenNutrientDistribution": "പോഷകങ്ങൾ ഒരേപോലെ എത്തുന്നില്ല",
"jeevadhara.overview.aControlledBionutrientSystemX1": "നിയന്ത്രിത ജൈവ പോഷക സംവിധാനം + X1",
"jeevadhara.overview.agedManureCompostSoilCocopeat": "പഴകിയ ചാണകം, കമ്പോസ്റ്റ്, മണ്ണ്, ചകിരിച്ചോർ, നേർപ്പിച്ച മൂത്രം എന്നിവ നിയന്ത്രിത ജൈവ പോഷക മിശ്രിതമായി തയ്യാറാക്കി, സ്ഥിരപ്പെടുത്തി, BhoomiShakti X1 ഉപയോഗിച്ച് മണ്ണിൽ കലർത്തുന്നു.",
"jeevadhara.overview.objectives": "ലക്ഷ്യങ്ങൾ",
"jeevadhara.overview.developAControlledBionitrogenSystem": "നിയന്ത്രിത ജൈവ നൈട്രജൻ സംവിധാനം വികസിപ്പിക്കുക",
"jeevadhara.overview.improveSoilBiologicalActivityAnd": "മണ്ണിലെ ജൈവ പ്രവർത്തനം മെച്ചപ്പെടുത്തുക, മണ്ണിരകളെ പിന്തുണയ്ക്കുക",
"jeevadhara.overview.enhanceSustainableCropProductivity": "സുസ്ഥിരമായ വിളവ് വർദ്ധിപ്പിക്കുക",
"jeevadhara.overview.reduceDependenceOnChemicalFertilizers": "രാസവളങ്ങളെ ആശ്രയിക്കുന്നത് കുറയ്ക്കുക",
"jeevadhara.overview.reduceManualSoilMixingWith": "BhoomiShakti X1 ഉപയോഗിച്ച് കൈകൊണ്ടുള്ള മണ്ണ് കലർത്തൽ കുറയ്ക്കുക",
"jeevadhara.simple.howJeevadharaWorksInSimple": "JeevaDhara എങ്ങനെ പ്രവർത്തിക്കുന്നു — ലളിതമായി",
