"jeevadhan.top.circularRuralEconomyRenewableAgriculture": "ചാക്രിക ഗ്രാമീണ സമ്പദ്‌വ്യവസ്ഥയും പുനരുപയോഗ കൃഷിയും",
"jeevadhan.top.turningRuralBiomassIntoRenewable": "ഗ്രാമീണ ബയോമാസിനെ പുനരുപയോഗ മൂല്യമാക്കി മാറ്റുന്നു — നാട്ടിൽ ലഭ്യമായ കന്നുകാലി ബയോമാസിനെ ഉപകാരപ്രദമായ പുനരുപയോഗ ഊർജമായും കാർഷിക വിഭവങ്ങളായും മാറ്റുന്നു.",
"jeevadhan.top.transformRuralBiomassFromA": "“ഗ്രാമീണ ബയോമാസിനെ ഒരു മാലിന്യ പ്രശ്നത്തിൽ നിന്ന് ഊർജത്തിന്റെയും മൂല്യത്തിന്റെയും കാർഷിക സുസ്ഥിരതയുടെയും ഉറവിടമാക്കി മാറ്റുക.”",
