"jeevadhan.overview.noOrganizedDigitalBiomassNetwork": "ചിട്ടയായ ഡിജിറ്റൽ ബയോമാസ് ശൃംഖലയില്ല",
"jeevadhan.overview.needForSustainableOrganicresourceManagement": "ജൈവ വിഭവങ്ങളുടെ സുസ്ഥിര പരിപാലനം ആവശ്യം",
