"farmerTools.weather.rainExpectedWhenTheForecast": "<t0>മഴ പ്രതീക്ഷിക്കുന്നു</t0>: ആ ദിവസത്തെ പ്രവചനം <t1>{0} mm അല്ലെങ്കിൽ അതിൽ കൂടുതൽ</t1> ആകുമ്പോൾ — {1} മണിക്കൂറിൽ “നേരിയ മഴ” എന്നതിന് ഇന്ത്യൻ കാലാവസ്ഥാ വകുപ്പ് നിശ്ചയിച്ച കുറഞ്ഞ പരിധിയാണിത്.",
"farmerTools.weather.veryHotWhenTheForecast": "<t0>കടുത്ത ചൂട്</t0>: പ്രവചിച്ച കൂടിയ താപനില <t1>{0} °C അല്ലെങ്കിൽ അതിൽ കൂടുതൽ</t1> ആകുമ്പോൾ — സമതലങ്ങൾക്ക് IMD നിശ്ചയിച്ച ഉഷ്ണതരംഗ പരിധിയാണിത് (മലയോര മേഖലകളിൽ ഇതിലും കുറഞ്ഞ പരിധിയാണ്).",
"farmerTools.weather.possibleSprayHoursAreDaytime": "<t0>തളിക്കാൻ പറ്റിയേക്കാവുന്ന മണിക്കൂറുകൾ</t0> എന്നാൽ പകൽ സമയത്ത് ({0} AM – {1} PM) മഴ പ്രവചിക്കാത്ത, കാറ്റ് <t1>{2}-നും {3} km/h-നും ഇടയിലുള്ള</t1> ({4}–{5} mph) മണിക്കൂറുകളാണ് — കീടനാശിനിയുടെ ഉത്തരവാദിത്തമുള്ള ഉപയോഗത്തിനുള്ള മാർഗനിർദ്ദേശങ്ങളിൽ ശുപാർശ ചെയ്യുന്ന പരിധിയാണിത്. തീരെ കാറ്റില്ലാത്തപ്പോഴും മരുന്ന് പാറിപ്പോകാം.",
"farmerTools.weather.forecastWindIsAt0": "പ്രവചിച്ച കാറ്റ് {0} m ഉയരത്തിലുള്ളതും നിങ്ങളുടെ പ്രദേശത്തിനുള്ളതുമാണ്, നിങ്ങളുടെ കൃത്യമായ വയലിനുള്ളതല്ല.",
"farmerTools.weather.sourcesIndiaMeteorologicalDepartmentRainfall": "ഉറവിടങ്ങൾ: <t0>ഇന്ത്യൻ കാലാവസ്ഥാ വകുപ്പ്</t0> (മഴയുടെ പദാവലി, <t1>ഉഷ്ണതരംഗ നിർവചനം</t1>) · <t2>Pesticide Environmental Stewardship — കാലാവസ്ഥ വിലയിരുത്തുക</t2>",
"farmerTools.weather.weatherbasedGuidanceIsInformationalAlways": "<t0>കാലാവസ്ഥ അടിസ്ഥാനമാക്കിയ മാർഗനിർദ്ദേശം വിവരത്തിന് മാത്രമാണ്.</t0> തളിക്കും മുമ്പ് എപ്പോഴും വയലിലെ സ്ഥിതി, വിളയുടെ ആവശ്യങ്ങൾ, ഉൽപ്പന്ന ലേബലിലെ നിർദ്ദേശങ്ങൾ എന്നിവ പരിഗണിക്കുക.",
"farmerTools.weather.weatherDataByOpenmeteocomOnly": "<t0>കാലാവസ്ഥാ ഡാറ്റ: Open-Meteo.com</t0> · പ്രവചനം ലഭിക്കാൻ നിങ്ങൾ തിരഞ്ഞെടുക്കുന്ന സ്ഥലപ്പേരോ സ്ഥാനമോ മാത്രമേ അയയ്ക്കുന്നുള്ളൂ. ഒന്നും സൂക്ഷിക്കുന്നില്ല.",
