"farmerTools.schemes.linksGoOnlyToOfficial": "ലിങ്കുകൾ ഇന്ത്യാ ഗവൺമെന്റിന്റെ ഔദ്യോഗിക വെബ്സൈറ്റുകളിലേക്ക് മാത്രമാണ് പോകുന്നത്. ഒരു ഔദ്യോഗിക ഉറവിടം സ്ഥിരീകരിക്കുന്നിടത്ത് മാത്രമേ ഹെൽപ്‌ലൈൻ നമ്പറുകൾ കാണിക്കുന്നുള്ളൂ — ഓരോന്നിനും അതിന്റെ ഉറവിടം കാണിച്ചിട്ടുണ്ട്.",
