"farmerTools.schemes.eligibilityBenefitsAndApplicationSteps": "യോഗ്യത, ആനുകൂല്യങ്ങൾ, അപേക്ഷിക്കേണ്ട രീതി എന്നിവ മാറാം. ഏറ്റവും പുതിയ വിവരങ്ങൾക്ക് എപ്പോഴും ഔദ്യോഗിക വെബ്സൈറ്റോ ഹെൽപ്‌ലൈനോ നോക്കുക. BhoomiShakti-ക്ക് ഈ സർക്കാർ സേവനങ്ങളുമായി ബന്ധമില്ല. വിവരങ്ങൾ പരിശോധിച്ചത്: ഒക്ടോബർ {0}.",
"farmerTools.main.farmerSafetyInformationNote": "കർഷക സുരക്ഷാ, വിവര കുറിപ്പ്",
"farmerTools.main.theseToolsSupportYourDecisions": "ഈ ടൂളുകൾ നിങ്ങളുടെ തീരുമാനങ്ങൾക്ക് ഒരു സഹായം മാത്രമാണ്; നിങ്ങളുടെ പ്രദേശത്തെ കൃഷി ഓഫീസർ, കൃഷി വിജ്ഞാന കേന്ദ്രം, കിസാൻ കോൾ സെന്റർ ({0}-{1}-{2}) എന്നിവരുടെ ഉപദേശത്തിന് ഇവ പകരമല്ല.",
"farmerTools.main.beforeSprayingReadAndFollow": "തളിക്കും മുമ്പ് ഉൽപ്പന്ന ലേബൽ വായിച്ച് അത് പാലിക്കുക, അതിൽ പറയുന്ന സുരക്ഷാ ഉപകരണങ്ങൾ ധരിക്കുക.",
"farmerTools.main.weatherForecastsCanChangeCheck": "കാലാവസ്ഥാ പ്രവചനങ്ങൾ മാറാം. പണി ചെയ്യുന്ന ദിവസം വീണ്ടും നോക്കുക.",
"farmerTools.main.theLandConverterAndProfit": "ഭൂമി അളവ് കൺവെർട്ടറും ലാഭ പ്ലാനറും നിങ്ങളുടെ ബ്രൗസറിൽ മാത്രമാണ് പ്രവർത്തിക്കുന്നത്. നിങ്ങൾ ടൈപ്പ് ചെയ്യുന്നത് BhoomiShakti-ക്ക് ലഭിക്കുന്നില്ല, BhoomiShakti അത് സൂക്ഷിക്കുന്നുമില്ല.",
"farmerTools.contact.moreThanToolsOneEcosystem": "ടൂളുകൾ മാത്രമല്ല — <t0>ഒരൊറ്റ ഇക്കോസിസ്റ്റം.</t0>",
"farmerTools.contact.fromAgricultureIntelligenceToSolar": "കാർഷിക ഇന്റലിജൻസ് മുതൽ സോളാർ യന്ത്രങ്ങളും മണ്ണിന്റെ ആരോഗ്യവും വരെ, കർഷകർക്ക് വേണ്ട സേവനങ്ങളെ BhoomiShakti ബന്ധിപ്പിക്കുന്നു.",
