"team.top.theRootsBehindBhoomishakti": "<t0>BhoomiShakti-യുടെ</t0> പിന്നിലെ വേരുകൾ.",
"team.top.oneFounderSixBuildersAnd": "ഒരു ഫൗണ്ടർ, ആറ് നിർമ്മാതാക്കൾ, എട്ട് കണ്ടുപിടിത്തങ്ങൾ. എഞ്ചിനീയറിംഗ്, സോഫ്റ്റ്‌വെയർ, മണ്ണ് ശാസ്ത്രം, ഡിസൈൻ — എല്ലാം പരസ്പരം ബന്ധിപ്പിച്ച ഒരൊറ്റ കാർഷിക ഇക്കോസിസ്റ്റത്തിനായി പ്രവർത്തിക്കുന്നു.",
