"team.members.filterByExpertiseHoverA": "വൈദഗ്ധ്യം അനുസരിച്ച് തിരഞ്ഞെടുക്കുക, ഓരോരുത്തരും ഏതെല്ലാം പ്രോജക്ടുകൾ നിർമ്മിക്കുന്നുവെന്ന് കാണാൻ കാർഡിൽ ഹോവർ ചെയ്യുക, മുഴുവൻ വിവരത്തിന് പ്രൊഫൈൽ തുറക്കുക.",
