"team.map.whoBuildsWhat": "ആര് എന്ത് നിർമ്മിക്കുന്നു",
"team.map.peopleConnectedToEveryProject": "<t0>ഓരോ പ്രോജക്ടുമായും</t0> ബന്ധപ്പെട്ട ആളുകൾ.",
"team.map.selectAPersonToSee": "ഒരാളെ തിരഞ്ഞെടുത്താൽ അവരുടെ പ്രോജക്ടുകൾ കാണാം, ഒരു പ്രോജക്ട് തിരഞ്ഞെടുത്താൽ അത് ആര് നിർമ്മിക്കുന്നുവെന്ന് കാണാം. ഓരോ പ്രൊഫൈലിലും കൊടുത്തിരിക്കുന്ന പ്രോജക്ടുകളിൽ നിന്നാണ് ഈ ബന്ധങ്ങൾ.",
