"contact.main.youCanSendARental": "നിങ്ങൾക്ക് ഒരു <t0>വാടക അല്ലെങ്കിൽ ഉൽപ്പന്ന അന്വേഷണം</t0> അയയ്ക്കാം. ഈ വെബ്സൈറ്റ് വിലയോ ലഭ്യതയോ പണമിടപാടോ കാണിക്കുന്നില്ല. നിങ്ങളുടെ അപേക്ഷ ചർച്ച ചെയ്യാൻ ടീം മറുപടി നൽകും.",
