"contact.main.yesOnBrowsersThatSupport": "അതെ, വോയ്സ് ടൈപ്പിംഗ് പിന്തുണയ്ക്കുന്ന ബ്രൗസറുകളിൽ (ഉദാഹരണത്തിന് Android-ലെയോ ഡെസ്ക്ടോപ്പിലെയോ Chrome). മൈക്രോഫോണിൽ ടാപ്പ് ചെയ്ത് ഇംഗ്ലീഷ്, हिन्दी അല്ലെങ്കിൽ ಕನ್ನಡ തിരഞ്ഞെടുക്കുക. അയയ്ക്കും മുമ്പ് ദയവായി എഴുതിവന്നത് പരിശോധിക്കുക.",
