"contact.live.youAppearToBeOffline": "നിങ്ങൾ ഓഫ്‌ലൈനാണെന്ന് തോന്നുന്നു. നിങ്ങളുടെ സന്ദേശം ഈ ഉപകരണത്തിൽ സേവ് ചെയ്തിട്ടുണ്ട്, കണക്ഷൻ തിരികെ വരുമ്പോൾ തനിയെ അയയ്ക്കും. ഈ പേജ് തുറന്നുതന്നെ വെക്കുക.",
"contact.live.plantedAndWaitingForRain": "നട്ടു, മഴ കാത്തിരിക്കുന്നു — നിങ്ങൾ ഓൺലൈനാകുമ്പോൾ ഇത് അയയ്ക്കും.",
"diary.top.productConceptFutureFarmerApp": "<t0/>ഉൽപ്പന്ന ആശയം · ഭാവിയിലെ കർഷക ആപ്പ്",
"diary.top.theTaglineInSixIndian": "ആറ് ഇന്ത്യൻ ഭാഷകളിലെ ടാഗ്‌ലൈൻ. ഹിന്ദി: हर खेत की कहानी, अब आपकी डायरी में. കന്നഡ: ಪ್ರತಿ ಹೊಲದ ಕಥೆ, ಈಗ ನಿಮ್ಮ ಡೈರಿಯಲ್ಲಿ. തമിഴ്: ஒவ்வொரு வயலின் கதையும், இப்போது உங்கள் டைரியில். തെലുങ്ക്: ప్రతి పొలం కథ, ఇప్పుడు మీ డైరీలో. മറാഠി: प्रत्येक शेताची कहाणी, आता तुमच्या डायरीत. മലയാളം: ഓരോ കൃഷിയിടത്തിന്റെയും കഥ, ഇനി നിങ്ങളുടെ ഡയറിയിൽ.",
"diary.top.yourFarmYourRecordsYour": "നിങ്ങളുടെ കൃഷിയിടം. നിങ്ങളുടെ രേഖകൾ. നിങ്ങളുടെ യാത്ര.",
"diary.top.bhoomishaktiDiaryIsEnvisionedAs": "ദിവസേനയുള്ള കൃഷിപ്പണികൾ, ചെലവുകൾ, വിള രേഖകൾ, സീസൺ ചരിത്രം എന്നിവ ഒരിടത്ത്, സ്വന്തം ഭാഷയിൽ ചിട്ടപ്പെടുത്താൻ കർഷകരെ സഹായിക്കുന്ന ലളിതമായ ഒരു ഡിജിറ്റൽ കൃഷി ഡയറിയായാണ് BhoomiShakti Diary സങ്കൽപ്പിച്ചിരിക്കുന്നത്.",
