"diary.designed.ideaBigPictureButtonsRecord": "<t0>ആശയം:</t0> വലിയ ചിത്ര ബട്ടണുകൾ വഴി ഏറ്റവും പതിവുള്ള പണികൾ ഒന്നോ രണ്ടോ ടാപ്പിൽ രേഖപ്പെടുത്താം.",
"diary.designed.cropMemory": "വിള ഓർമ്മ",
