"diary.designed.ideaEveryRecordIsFiled": "<t0>ആശയം:</t0> ഓരോ രേഖയും അതിന്റെ വിളയ്ക്കും വയലിനും കീഴിൽ തനിയെ ചേർക്കുന്നു.",
