"diary.designed.ideaACompletePrintableRecord": "<t0>ആശയം:</t0> മുഴുവൻ സീസണിന്റെയും പൂർണ്ണമായ, പ്രിന്റ് ചെയ്യാവുന്ന രേഖ.",
