"diary.designed.farmerProblemFarmHistoryIs": "<t0>കർഷകന്റെ പ്രശ്നം:</t0> കൃഷിയിട ചരിത്രം പല വർഷങ്ങളിലും പല നോട്ടുബുക്കുകളിലുമായി ചിതറിക്കിടക്കുന്നു.",
