"diary.designed.ideaTheFarmerChoosesWhich": "<t0>ആശയം:</t0> ഏതെല്ലാം രേഖകൾ പങ്കിടണമെന്ന് കർഷകൻ തീരുമാനിക്കുന്നു — ഒന്നും തനിയെ പങ്കിടുന്നില്ല.",
