"diary.designed.farmerProblemNotEveryFarmer": "<t0>കർഷകന്റെ പ്രശ്നം:</t0> എല്ലാ കർഷകർക്കും ടൈപ്പ് ചെയ്യാൻ എളുപ്പമല്ല.",
